head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getTotalHeaderCol]<br/>Header 영역에 정의된 Column 갯수를 반환합니다.",
    "validation" : [
        "options.defaultColumn 파라미터가 true 면 rowNumVisible/rowStatusVisible 로 표시된 RowNum, RowStatus Column 을 반환값에 포함하고, false(기본값)면 표시 여부에 관계없이 Header 영역에 정의된 Column 갯수만 반환해야 합니다.",
        "Header 영역에 정의된 전체 Column 의 갯수를 반환해야 합니다.",
        "숨겨진 Column 은 반환값에 포함됩니다.",
        "Header 가 MultiLine 이면 각 Line 의 Column 갯수가 모두 포함됩니다.",
        "디자인 시 병합된 Column 은 1 개로 처리됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (MultiLine 구성 : 한 레코드(Row)를 2개의 Line 으로 표시)
//  - Header 물리적 컬럼 배치
//    Line1 : merge(rowSpan=2) + name + age(숨김)
//    Line2 : dept + memo
//  - merge 컬럼은 rowSpan="2" 로 두 Line 에 걸쳐 병합됨 → 디자인 시 병합된 Column 은 1 개로 처리됨
//  - rowNumVisible/rowStatusVisible true → 기본 컬럼 2개 존재 (defaultColumn 옵션에 의해 반환 포함 여부 결정)
//  - age 컬럼은 setColumnVisible(false) 로 숨기지만 반환값에는 포함됨
//  - 예상 getTotalHeaderCol({defaultColumn:false}) = merge(1) + name + age(숨김) + dept + memo = 5
//  - 예상 getTotalHeaderCol({defaultColumn:true})  = 5 + RowNum(1) + RowStatus(1) = 7
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine/병합/숨김/RowNum·RowStatus 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="MultiLine 2 Line Header: Line1=merge(병합,rowSpan2)·name·age(숨김) / Line2=dept·memo. RowNum/RowStatus 표시. 병합 1개, 숨김 age 포함 → defaultColumn false 예상 5 / defaultColumn true 예상 7"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="merge" name="merge" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="age" name="age" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "merge": "G1", "name": "John", "age": "30", "dept": "영업", "memo": "메모0" },
        { "merge": "G2", "name": "Jane", "age": "28", "dept": "기획", "memo": "메모1" },
        { "merge": "G3", "name": "Mike", "age": "41", "dept": "개발", "memo": "메모2" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    //  - rowNumVisible / rowStatusVisible true : RowNum/RowStatus Column 표시 (defaultColumn 옵션 검증용)
    let properties = {
        dataList: "data:dlt_bind",
        rowNumVisible: "true",
        rowStatusVisible: "true"
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (MultiLine : header/gBody 각각 <w2:row> 2개, merge 컬럼은 rowSpan="2")
    //  마지막 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:560px;height:280px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getTotalHeaderCol MultiLine 테스트 그리드"></w2:caption>';
    // Header : merge(rowSpan2) + name / age 와 dept / memo
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column rowSpan="2" width="120" style="" inputType="text" id="hcol_merge" value="그룹"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol_name" value="이름"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_age" value="나이"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol_dept" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_memo" value="메모"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // gBody : merge(rowSpan2, Line1) + name(Line1) + age(Line1) / dept(Line2) + memo(Line2)
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // merge : rowSpan="2" 로 두 Line 에 걸쳐 병합 → 1 개로 처리
    strTarget += '<w2:column rowSpan="2" width="120" style="" inputType="text" id="merge" dataList="merge"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // age : 숨김 처리 대상이나 반환값에는 포함됨
    strTarget += '<w2:column width="*" style="" inputType="text" id="age" dataList="age"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // age 컬럼(Body 컬럼 인덱스 2) 숨김 : 반환값에는 여전히 포함되는지 검증용
    //  컬럼 순서(RowNum/RowStatus 제외) : 0=merge, 1=name, 2=age, 3=dept, 4=memo
    scwin.target1.setColumnVisible(2, false);
}



// getTotalHeaderCol 확인 : Header 영역에 정의된 Column 갯수를 반환
//  - par_defaultColumn 은 공통 gdl_boolean 바인딩 → value(1/2) 가 아닌 getText() 로 label(true/false) 을 가져옴
//  - getText() === ''     : 옵션 생략 → getTotalHeaderCol() (기본 defaultColumn=false → 예상 5)
//  - getText() === 'true'  : getTotalHeaderCol({defaultColumn:true})  → RowNum/RowStatus 포함 (예상 7)
//  - getText() === 'false' : getTotalHeaderCol({defaultColumn:false}) → Header 정의 컬럼만 (예상 5)
//  - 숨김 age 포함 / MultiLine 2 Line 합산 / 병합 merge 는 1 개로 처리
scwin.btn_getTotalHeaderCol_onclick = function () {
    let defText = par_defaultColumn.getText();
    let rtn, out;

    if (defText === '') {
        // 파라미터 생략 (기본값 false)
        rtn = target1.getTotalHeaderCol();
        out = "getTotalHeaderCol() → " + rtn;
    } else {
        let defaultColumn = defText === 'true';
        rtn = target1.getTotalHeaderCol({ defaultColumn: defaultColumn });
        out = "getTotalHeaderCol({defaultColumn:" + defaultColumn + "}) → " + rtn;
    }
    wf_body_bottom.getObj("scwin").setReturnValue(out);
}
